import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.File;

/**
 * Draws curseforge/icon.png from scratch: a white border, a shore with hills, a square sun and a small figure,
 * all of it mirrored in the water below, and "SHADERS / COMPANION" in hand-made pixel letters. No font, no asset
 * from any mod or shader pack, nothing generated by AI.
 * Run from the repo root: java curseforge/MakeIcon.java curseforge/icon.png
 */
public class MakeIcon {
    static final int GRID = 52;
    static final int CELL = 10;
    static final int BORDER = 2;
    /** The first row of water: everything above it is mirrored below it. */
    static final int WATERLINE = 26;

    static final int WHITE = 0xFFFFFF;
    static final int OUTLINE = 0x0B1626;
    static final int SKY_TOP = 0x2C5AA0;
    static final int SKY_LOW = 0xBCD9EE;
    static final int SUN = 0xFFF3B8;
    static final int SUN_RIM = 0xFFD98A;
    static final int FAR_HILL = 0x5E8C6C;
    static final int NEAR_HILL = 0x2F6B3F;
    static final int NEAR_HILL_LIGHT = 0x3F8550;
    static final int SAND = 0xDCCB8E;
    static final int WATER_TINT = 0x0E2C55;
    static final int GLINT = 0x9CC6EA;
    static final int HAIR = 0x3A2A1A;
    static final int SKIN = 0xDDAA7C;
    static final int SHIRT = 0x1FA39B;
    static final int LEGS = 0x2B3C8C;

    static final String[] S = {".###", "#...", "#...", ".##.", "...#", "...#", "###."};
    static final String[] H = {"#..#", "#..#", "#..#", "####", "#..#", "#..#", "#..#"};
    static final String[] A = {".##.", "#..#", "#..#", "####", "#..#", "#..#", "#..#"};
    static final String[] D = {"###.", "#..#", "#..#", "#..#", "#..#", "#..#", "###."};
    static final String[] E = {"####", "#...", "#...", "###.", "#...", "#...", "####"};
    static final String[] R = {"###.", "#..#", "#..#", "###.", "#.#.", "#..#", "#..#"};
    static final String[] C = {".###", "#...", "#...", "#...", "#...", "#...", ".###"};
    static final String[] O = {".##.", "#..#", "#..#", "#..#", "#..#", "#..#", ".##."};
    static final String[] M = {"#...#", "##.##", "#.#.#", "#.#.#", "#...#", "#...#", "#...#"};
    static final String[] P = {"###.", "#..#", "#..#", "###.", "#...", "#...", "#..."};
    static final String[] N = {"#..#", "##.#", "##.#", "#.##", "#.##", "#..#", "#..#"};
    static final String[] I = {"###", ".#.", ".#.", ".#.", ".#.", ".#.", "###"};

    public static void main(String[] args) throws Exception {
        int[][] color = new int[GRID][GRID];
        for (int y = 0; y < WATERLINE; y++) {
            for (int x = 0; x < GRID; x++) {
                color[y][x] = land(x, y);
            }
        }
        figure(color, 12, WATERLINE - 1);
        for (int y = WATERLINE; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                color[y][x] = water(color, x, y);
            }
        }

        boolean[][] text = new boolean[GRID][GRID];
        stamp(text, new String[][] {S, H, A, D, E, R, S}, 1, 5);
        stamp(text, new String[][] {C, O, M, P, A, N, I, O, N}, 1, 39);
        boolean[][] outline = grow(text);
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (text[y][x]) {
                    color[y][x] = WHITE;
                } else if (outline[y][x]) {
                    color[y][x] = OUTLINE;
                }
            }
        }

        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (x < BORDER || y < BORDER || x >= GRID - BORDER || y >= GRID - BORDER) {
                    color[y][x] = WHITE;
                }
            }
        }

        BufferedImage image = new BufferedImage(GRID * CELL, GRID * CELL, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < GRID * CELL; y++) {
            for (int x = 0; x < GRID * CELL; x++) {
                image.setRGB(x, y, color[y / CELL][x / CELL]);
            }
        }
        ImageIO.write(image, "png", new File(args[0]));
    }

    /** Sky with a square sun, two rows of hills and a strip of sand along the water. */
    static int land(int x, int y) {
        if (y == WATERLINE - 1) {
            return SAND;
        }
        int nearTop = WATERLINE - 4 - (int) Math.round(3.0 * wave(x, 9.0, 0.7) + 1.5 * wave(x, 4.0, 2.1));
        int farTop = WATERLINE - 8 - (int) Math.round(3.0 * wave(x, 15.0, 4.0) + 1.5 * wave(x, 6.0, 1.0));
        if (y >= nearTop) {
            return hash(x, y, 1) > 0.7 ? NEAR_HILL_LIGHT : NEAR_HILL;
        }
        if (y >= farTop) {
            return FAR_HILL;
        }
        int sunX = 36;
        int sunY = 13;
        int fromSun = Math.max(Math.abs(x - sunX), Math.abs(y - sunY));
        if (fromSun <= 2) {
            return SUN;
        }
        if (fromSun == 3) {
            return SUN_RIM;
        }
        return mix(SKY_TOP, SKY_LOW, y / (double) (WATERLINE - 2));
    }

    /** A block figure four cells wide standing with its feet on row footY. */
    static void figure(int[][] color, int left, int footY) {
        int[] rows = {HAIR, SKIN, SKIN, SHIRT, SHIRT, SHIRT, LEGS, LEGS};
        for (int i = 0; i < rows.length; i++) {
            int y = footY - (rows.length - 1 - i);
            for (int x = left; x < left + 4; x++) {
                boolean head = i < 3;
                if (!head || (x > left && x < left + 3) || i > 0) {
                    color[y][x] = rows[i];
                }
            }
        }
        color[footY - 7][left] = mix(SKY_TOP, SKY_LOW, (footY - 7) / (double) (WATERLINE - 2));
        color[footY - 7][left + 3] = color[footY - 7][left];
    }

    /** The land's mirror image: darker and bluer with depth, each row pushed sideways a little, with a few glints. */
    static int water(int[][] land, int x, int y) {
        int depth = y - WATERLINE;
        int sourceY = WATERLINE - 1 - depth;
        int shift = depth < 2 ? 0 : (int) Math.round(wave(y, 2.2, 0.3) * Math.min(2.0, depth / 6.0));
        int sourceX = Math.max(0, Math.min(GRID - 1, x + shift));
        int source = sourceY >= 0 ? land[sourceY][sourceX] : SKY_TOP;
        int mirrored = mix(source, WATER_TINT, 0.38 + 0.25 * depth / (double) (GRID - WATERLINE));
        if (depth > 1 && hash(x / 3, y, 5) > 0.93) {
            return mix(mirrored, GLINT, 0.45);
        }
        return mirrored;
    }

    static double wave(int at, double length, double phase) {
        return Math.sin(at / length + phase);
    }

    /** Writes a line of letters, centred, with its top at row top. */
    static void stamp(boolean[][] text, String[][] letters, int gap, int top) {
        int width = -gap;
        for (String[] letter : letters) {
            width += letter[0].length() + gap;
        }
        int x = (GRID - width) / 2;
        for (String[] letter : letters) {
            for (int row = 0; row < letter.length; row++) {
                for (int column = 0; column < letter[row].length(); column++) {
                    if (letter[row].charAt(column) == '#') {
                        text[top + row][x + column] = true;
                    }
                }
            }
            x += letter[0].length() + gap;
        }
    }

    /** The cells within one cell of the text, corners included. */
    static boolean[][] grow(boolean[][] text) {
        boolean[][] grown = new boolean[GRID][GRID];
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                for (int dy = -1; dy <= 1 && !grown[y][x]; dy++) {
                    for (int dx = -1; dx <= 1; dx++) {
                        int ny = y + dy;
                        int nx = x + dx;
                        if (ny >= 0 && nx >= 0 && ny < GRID && nx < GRID && text[ny][nx]) {
                            grown[y][x] = true;
                            break;
                        }
                    }
                }
            }
        }
        return grown;
    }

    static int mix(int a, int b, double t) {
        t = Math.max(0.0, Math.min(1.0, t));
        int r = (int) Math.round(((a >> 16) & 0xFF) * (1.0 - t) + ((b >> 16) & 0xFF) * t);
        int g = (int) Math.round(((a >> 8) & 0xFF) * (1.0 - t) + ((b >> 8) & 0xFF) * t);
        int bl = (int) Math.round((a & 0xFF) * (1.0 - t) + (b & 0xFF) * t);
        return (r << 16) | (g << 8) | bl;
    }

    /** A repeatable value from 0 to 1 for a cell. */
    static double hash(int x, int y, int salt) {
        long h = x * 374761393L + y * 668265263L + salt * 2246822519L;
        h = (h ^ (h >>> 13)) * 1274126177L;
        h ^= h >>> 16;
        return (h & 0xFFFFFF) / (double) 0x1000000;
    }
}
